from hermes_tools import terminal
cmd = r"""
python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path)
ws=wb['Task']
errors=[]
# Expected formulas
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            col=get_column_letter(c)
            exp=f"=INDEX(Data!$H$21:$L$38, MATCH($D{r}, Data!$D$21:$D$38, 0), MATCH({col}$10, Data!$H$4:$L$4, 0))"
            if ws.cell(r,c).value != exp:
                errors.append((f'{col}{r}', ws.cell(r,c).value, exp))
for r in range(35,41):
    off=r-35
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f"=({col}{12+off} - {col}{19+off}) / {col}{26+off} * 100"
        if ws.cell(r,c).value != exp:
            errors.append((f'{col}{r}', ws.cell(r,c).value, exp))
stat_funcs={42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE',46:'PERCENTILE25',47:'PERCENTILE75'}
for r,fn in stat_funcs.items():
    for c in range(8,13):
        col=get_column_letter(c)
        if fn=='PERCENTILE25': exp=f'=PERCENTILE({col}35:{col}40,0.25)'
        elif fn=='PERCENTILE75': exp=f'=PERCENTILE({col}35:{col}40,0.75)'
        else: exp=f'={fn}({col}35:{col}40)'
        if ws.cell(r,c).value != exp:
            errors.append((f'{col}{r}', ws.cell(r,c).value, exp))
for c in range(8,13):
    col=get_column_letter(c)
    exp=f'=SUMPRODUCT({col}35:{col}40, {col}26:{col}31) / SUM({col}26:{col}31)'
    if ws.cell(50,c).value != exp:
        errors.append((f'{col}50', ws.cell(50,c).value, exp))
print('errors', len(errors))
for e in errors[:10]: print(e)
print('sheets', wb.sheetnames)
print('max rows/cols Task', ws.max_row, ws.max_column)
print('no PERCENTILE dotted:', all('PERCENTILE.' not in str(ws.cell(r,c).value) for r in range(1,ws.max_row+1) for c in range(1,ws.max_column+1)))
PY
"""
print(terminal(cmd, timeout=60)['output'])
